-- Guest direct-write guard; independent of the M2/M3 legacy policies.
CREATE POLICY m2b_contests_insert ON public.contests AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK (NOT coalesce((auth.jwt()->>'is_anonymous')::boolean, false));
CREATE POLICY m2b_contests_update ON public.contests AS RESTRICTIVE FOR UPDATE TO authenticated USING (NOT coalesce((auth.jwt()->>'is_anonymous')::boolean, false)) WITH CHECK (NOT coalesce((auth.jwt()->>'is_anonymous')::boolean, false));
CREATE POLICY m2b_contests_delete ON public.contests AS RESTRICTIVE FOR DELETE TO authenticated USING (NOT coalesce((auth.jwt()->>'is_anonymous')::boolean, false));
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.contests FROM anon;
CREATE POLICY m2b_contest_players_insert ON public.contest_players AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK (NOT coalesce((auth.jwt()->>'is_anonymous')::boolean, false));
CREATE POLICY m2b_contest_players_update ON public.contest_players AS RESTRICTIVE FOR UPDATE TO authenticated USING (NOT coalesce((auth.jwt()->>'is_anonymous')::boolean, false)) WITH CHECK (NOT coalesce((auth.jwt()->>'is_anonymous')::boolean, false));
CREATE POLICY m2b_contest_players_delete ON public.contest_players AS RESTRICTIVE FOR DELETE TO authenticated USING (NOT coalesce((auth.jwt()->>'is_anonymous')::boolean, false));
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.contest_players FROM anon;
