CREATE POLICY m2b_scans_update ON public.scans AS RESTRICTIVE FOR UPDATE TO authenticated USING (NOT coalesce((auth.jwt()->>'is_anonymous')::boolean, false)) WITH CHECK (NOT coalesce((auth.jwt()->>'is_anonymous')::boolean, false));
