CREATE POLICY m2b_profiles_insert ON public.profiles AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK (NOT coalesce((auth.jwt()->>'is_anonymous')::boolean, false));
CREATE POLICY m2b_profiles_update ON public.profiles AS RESTRICTIVE FOR UPDATE TO authenticated USING (NOT coalesce((auth.jwt()->>'is_anonymous')::boolean, false)) WITH CHECK (NOT coalesce((auth.jwt()->>'is_anonymous')::boolean, false));
CREATE POLICY m2b_profiles_delete ON public.profiles AS RESTRICTIVE FOR DELETE TO authenticated USING (NOT coalesce((auth.jwt()->>'is_anonymous')::boolean, false));
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.profiles FROM anon;
REVOKE INSERT, UPDATE ON public.profiles FROM authenticated;
GRANT UPDATE (display_name, avatar_url) ON public.profiles TO authenticated;
